"use strict";(globalThis.webpackChunkmy_website||=[]).push([[40465],{73241(e){e.exports=JSON.parse('{"slug":"babel-fees","title":"Babel Fees","short":"A proposed mechanism that would let users pay transaction fees using native tokens instead of ada (not yet live on mainnet).","category":"tokens","aliases":[],"mentalModel":null,"related":["eutxo","native-token","stake-pool"],"sources":[],"link":null,"level":"intermediate","body":"A proposed mechanism that would let users pay transaction fees using native tokens instead of ada. It is not yet live on mainnet. Liquidity providers, such as stake pool operators or independent third parties, would offer exchange rates for the tokens they accept and supply the matching ada. The fees still settle in ada behind the scenes, keeping ada central to the ecosystem while enabling broader participation. The design is made possible by Cardano\'s eUTXO model. See [Native Tokens](https://developers.cardano.org/docs/native-tokens/) on the Developer Portal."}')}}]);